// Checks the version is still awaiting approval and gathers everything the emails need.
const requested = $('Start').first().json.plan_version_id;
const v = $('Load Version').first().json;
const s = $('Load Submission').first().json;
if (!v || !v.id) throw new Error('Plan version not found: ' + requested + '. No approval email sent.');
if (v.status !== 'awaiting_approval') throw new Error('Plan version ' + v.id + ' is ' + v.status + ', expected awaiting_approval. No approval email sent.');
if (String(v.review_status || '').trim().toUpperCase() === 'HOLD') throw new Error('Plan version ' + v.id + ' has review status HOLD. Held plans are not sent for approval. No approval email sent.');
if (!s || !s.id) throw new Error('Submission ' + v.submission_id + ' not found for plan version ' + v.id + '. No approval email sent.');
const name = String(s.client_name || '').trim().replace(/\b\w/g, (c) => c.toUpperCase()) || 'there';
const goal = s.plan_goal === 'bank-loan' ? 'Bank Loan' : s.plan_goal === 'investor' ? 'Investor Pitch' : 'Personal Roadmap';
const safeName = name.replace(/[\\/:*?"<>|]/g, '').trim() || 'Client';
return [{ json: {
  plan_version_id: v.id,
  submission_id: v.submission_id,
  version: v.version,
  pdf_path: v.pdf_path,
  client_name: name,
  client_email: s.email || '',
  package: s.package || 'Unknown',
  plan_goal_label: goal,
  review_status: v.review_status || 'NOT RECORDED',
  review_notes: v.review_notes || 'No review notes were recorded for this version.',
  customer_subject: 'Your ' + goal + ' plan is ready',
  pdf_filename: 'IdeaToPlan - ' + safeName + '.pdf',
  // 48 hours unless the caller passes a shorter wait for testing.
  wait_minutes: Number($('Start').first().json.approval_wait_minutes) > 0 ? Number($('Start').first().json.approval_wait_minutes) : 2880,
} }];

// Approval request to Liz. The PDF link is a fresh 72 hour signed URL; the wait limit is 48 hours.
const p = $('Prepare Approval').first().json;
const signed = $input.first().json.signedURL;
if (!signed) throw new Error('Storage returned no signed URL for ' + p.pdf_path + '. No approval email sent.');
const url = 'https://yglmlnfsyzsvozxirlpo.supabase.co/storage/v1' + signed;
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inner = '<p style="font-size: 18px; margin-top: 0;"><strong>Ready for your review</strong></p>'
  + '<p style="margin: 0;">Client: ' + esc(p.client_name) + '</p><p style="margin: 0;">Email: ' + esc(p.client_email) + '</p><p style="margin: 0;">Package: ' + esc(p.package) + '</p><p style="margin: 0;">Order: ' + esc(p.submission_id) + '</p><p style="margin: 0 0 16px;">Version: ' + esc(p.version) + '</p>'
  + '<p style="margin: 0;"><strong>Review notes</strong></p><p style="margin: 0 0 4px;">Status: ' + esc(p.review_status) + '</p>'
  + '<pre style="white-space: pre-wrap; font-family: monospace; font-size: 12px; margin: 0 0 16px;">' + esc(p.review_notes) + '</pre>'
  + '<p style="margin: 0;"><a href="' + esc(url) + '">Open PDF</a></p><p style="margin: 0 0 16px;">Available for 72 hours from this email.</p>'
  + '<p style="margin: 0;"><strong>Approve:</strong> Send this version to the client.</p><p style="margin: 0 0 16px;"><strong>Request changes:</strong> Hold delivery for revision.</p>'
  + '<p>Approval expires after ' + (p.wait_minutes === 2880 ? '48 hours' : p.wait_minutes + ' minutes (test setting)') + '. No response means no delivery.</p>';
const html = '<table width="100%" cellpadding="0" cellspacing="0" style="font-family: Georgia, serif; max-width: 700px; margin: 0 auto;"><tr><td style="background: #1e3a5f; padding: 24px 32px; border-radius: 8px 8px 0 0;"><h1 style="color: #ffffff; margin: 0; font-size: 22px; letter-spacing: 1px;">IDEA TO PLAN</h1><p style="color: #a0b8d0; margin: 4px 0 0; font-size: 13px;">Internal Review</p></td></tr><tr><td style="padding: 32px; background: #ffffff; font-size: 15px; line-height: 1.8; color: #222; text-align: left;">' + inner + '</td></tr></table>';
return [{ json: { ...p, approval_subject: 'Approve: ' + p.package + ' plan for ' + p.client_name + ' (' + p.review_status + ')', approval_html: html } }];

// Customer delivery email. The PDF comes from Storage, never from the earlier run.
const p = $('Prepare Approval').first().json;
const item = $input.first();
if (!item.binary || !item.binary.data) throw new Error('PDF download returned no file for ' + p.pdf_path + '. Row stays sending; nothing was sent.');
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inner = '<p style="margin-top: 0;">Hi ' + esc(p.client_name) + ',</p>'
  + '<p>Your business plan is attached. I\'ve personally reviewed it before delivery.</p>'
  + '<p>Have a question about your plan? Reply here and we\'ll help.</p>'
  + '<p>Thank you for trusting IdeaToPlan with your idea.</p>'
  + '<p style="margin-top: 32px;">Best,<br><strong>Elizabeth Alfond</strong><br><span style="font-size: 13px; color: #888;">Founder, IdeaToPlan<br>ideatoplan.to</span></p>';
const html = '<table width="100%" cellpadding="0" cellspacing="0" style="font-family: Georgia, serif; max-width: 700px; margin: 0 auto;"><tr><td style="background: #1e3a5f; padding: 24px 32px; border-radius: 8px 8px 0 0;"><h1 style="color: #ffffff; margin: 0; font-size: 22px; letter-spacing: 1px;">IDEA TO PLAN</h1><p style="color: #a0b8d0; margin: 4px 0 0; font-size: 13px;">Business Planning Service</p></td></tr><tr><td style="padding: 32px; background: #ffffff; font-size: 15px; line-height: 1.8; color: #222;">' + inner + '</td></tr><tr><td style="background: #1e3a5f; padding: 20px 32px; border-radius: 0 0 8px 8px; text-align: center;"><p style="color: #a0b8d0; margin: 0; font-size: 12px;">Built for founders ready to leap. IdeaToPlan.to</p></td></tr></table>';
return [{
  json: { ...p, customer_html: html, send_attempted_at: new Date().toISOString() },
  binary: { data: { ...item.binary.data, fileName: p.pdf_filename, mimeType: 'application/pdf' } },
}];

// Classifies a failed customer send by what is actually known. n8n's error output carries only a text message.
// local_validation: n8n refused the recipient before transmitting anything. Nothing was sent: send_failed.
// gmail_rejection:  Gmail verifiably refused the message: send_failed. Only patterns verified against n8n source are listed.
// uncertain:        anything else. The message may have gone out: send_unknown. This is the safe default.
const e = $input.first().json || {};
const p = $('Build Customer Email').first().json;
const raw = e.error;
const msg = String((raw && typeof raw === 'object' ? (raw.message || raw.description) : raw) || e.message || 'No error message returned');
const LOCAL_VALIDATION = [/^Invalid email address\b/i];
// n8n 2.20.9 produces this exact text only for an HTTP 400 response (node-api.error.ts, STATUS_CODE_MESSAGES['400']).
// A 400 needs a response from Gmail, so the message was refused, not lost. Other 4xx and all 5xx texts stay uncertain.
const GMAIL_REJECTION = [/^Bad request - please check your parameters\b/];
let source = 'uncertain';
if (LOCAL_VALIDATION.some((r) => r.test(msg))) source = 'local_validation';
else if (GMAIL_REJECTION.some((r) => r.test(msg))) source = 'gmail_rejection';
const status = source === 'uncertain' ? 'send_unknown' : 'send_failed';
return [{ json: { ...p, send_status: status, error_source: source, error_message: msg } }];
